// Deal Risk: deterministic scenario, rental metrics, and explainable risk flags.
const deal = $input.item.json;

const num = (value, fallback = 0) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const strategy = String(deal.strategyMode || 'fix_and_flip').toLowerCase();
const monthlyRent = num(deal.monthlyRent);
const annualTaxes = num(deal.annualTaxes, Math.round(num(deal.askingPrice) * 0.012));
const annualInsurance = num(deal.annualInsurance, Math.round(num(deal.askingPrice) * 0.006));
const monthlyHoa = num(deal.monthlyHoa);
const vacancyPct = clamp(num(deal.vacancyPct, 0.08), 0, 0.35);
const maintenancePct = clamp(num(deal.maintenancePct, 0.08), 0, 0.30);
const holdingMonths = Math.max(1, num(deal.holdingMonths, 6));
const arv = num(deal.arvEstimate);
const repairs = num(deal.repairEstimate);
const purchase = num(deal.maxOffer || deal.askingPrice);
const loanAmount = num(deal.loanAmount);
const monthlyPI = num(deal.monthlyPI);
const annualGrossRent = monthlyRent * 12;
const effectiveGrossIncome = annualGrossRent * (1 - vacancyPct);
const annualOperatingExpenses = annualTaxes + annualInsurance + monthlyHoa * 12 + annualGrossRent * maintenancePct;
const noi = Math.round(effectiveGrossIncome - annualOperatingExpenses);
const capRate = purchase > 0 ? Number((noi / purchase * 100).toFixed(2)) : null;
const annualDebtService = monthlyPI * 12;
const dscr = annualDebtService > 0 ? Number((noi / annualDebtService).toFixed(2)) : null;
const annualCashFlow = Math.round(noi - annualDebtService);
const cashInvested = Math.max(1, purchase - loanAmount + repairs);
const cashOnCash = Number((annualCashFlow / cashInvested * 100).toFixed(2));

const scenario = (name, arvFactor, repairFactor, rentFactor, rateDelta) => {
  const scenarioArv = Math.round(arv * arvFactor);
  const scenarioRepairs = Math.round(repairs * repairFactor);
  const scenarioValueSpread = scenarioArv - purchase - scenarioRepairs;
  const scenarioRent = monthlyRent * rentFactor;
  const scenarioNOI = Math.round((scenarioRent * 12 * (1 - vacancyPct)) - (annualTaxes + annualInsurance + monthlyHoa * 12 + scenarioRent * 12 * maintenancePct));
  const scenarioDebt = annualDebtService * (1 + rateDelta);
  return { name, arv: scenarioArv, repairs: scenarioRepairs, monthlyRent: Math.round(scenarioRent), netEquitySpread: scenarioValueSpread, capRate: purchase > 0 ? Number((scenarioNOI / purchase * 100).toFixed(2)) : null, dscr: scenarioDebt > 0 ? Number((scenarioNOI / scenarioDebt).toFixed(2)) : null };
};

const scenarios = [
  scenario('downside', 0.90, 1.20, 0.90, 0.10),
  scenario('base', 1.00, 1.00, 1.00, 0),
  scenario('upside', 1.08, 0.90, 1.05, -0.05),
];
const risks = [];
if (!arv || deal.arvConfidence === 'Low') risks.push({ severity: 'high', code: 'weak_arv', message: 'ARV is unavailable or based on low-confidence market data.' });
if (scenarios[0].netEquitySpread <= 0) risks.push({ severity: 'high', code: 'downside_loss', message: 'Downside flip scenario has no projected equity spread.' });
if (strategy === 'long_term_rental' || strategy === 'brrrr') {
  if (!monthlyRent) risks.push({ severity: 'high', code: 'missing_rent', message: 'Rental strategy needs a verified market-rent input.' });
  if (dscr !== null && dscr < 1.20) risks.push({ severity: 'high', code: 'low_dscr', message: 'Base-case DSCR is below the 1.20 underwriting threshold.' });
  if (capRate !== null && capRate < 5) risks.push({ severity: 'medium', code: 'low_cap_rate', message: 'Base-case cap rate is below 5%.' });
}
if (repairs > arv * 0.25) risks.push({ severity: 'medium', code: 'high_rehab', message: 'Repair budget exceeds 25% of estimated ARV.' });
if (!deal.medianHomeValue) risks.push({ severity: 'medium', code: 'missing_market_context', message: 'No Census market-value context was returned.' });
if (!deal.idempotencyKey) risks.push({ severity: 'medium', code: 'duplicate_check_missing', message: 'No idempotency key is present; duplicate submissions cannot be safely identified.' });

const downside = scenarios[0];
const recommendation = risks.some((risk) => risk.severity === 'high') ? 'reject_or_reprice' : downside.netEquitySpread > 0 ? 'review' : 'hold';
return { json: { ...deal, strategyMode: strategy, rentalMetrics: { annualGrossRent, effectiveGrossIncome: Math.round(effectiveGrossIncome), annualOperatingExpenses: Math.round(annualOperatingExpenses), noi, capRate, dscr, annualCashFlow, cashOnCash }, scenarios, riskRegister: risks, recommendation, humanReviewRequired: true, reviewStatus: 'Under Review', auditTrail: [{ stage: 'scenario_risk_engine', at: new Date().toISOString(), strategyMode: strategy, recommendation }] } };
